import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"QEMU testing","description":"","frontmatter":{},"headers":[],"relativePath":"dev/qemu-testing.md","filePath":"dev/qemu-testing.md"}'),i={name:"dev/qemu-testing.md"};function n(d,e,r,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="qemu-testing" tabindex="-1">QEMU testing <a class="header-anchor" href="#qemu-testing" aria-label="Permalink to &quot;QEMU testing&quot;">​</a></h1><p>How the project actually tests in QEMU - the same recipes the release gates use.</p><h2 id="interactive-boot" tabindex="-1">Interactive boot <a class="header-anchor" href="#interactive-boot" aria-label="Permalink to &quot;Interactive boot&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios      # default: 512M, e1000 + user net, serial on stdio</span></span>
<span class="line"><span>make run-uefi      # q35 + OVMF</span></span>
<span class="line"><span>make run-bios-gui  # display on (for the TUI)</span></span></code></pre></div><p>The <code>run-*</code> targets build the ISO and a fresh <code>etc.img</code> (the 32 MiB FAT32 /etc volume) so persistence tests start clean.</p><h2 id="deterministic-boot-log-testing" tabindex="-1">Deterministic boot-log testing <a class="header-anchor" href="#deterministic-boot-log-testing" aria-label="Permalink to &quot;Deterministic boot-log testing&quot;">​</a></h2><p>The regression suite (<code>tools/run_fix4_regression.py</code>) drives QEMU through pexpect over <code>-serial mon:stdio</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><p>It waits for the <code>oc&gt;</code> prompt, then runs the fixed command battery (uname, help -a, heaptest, fstest, cryptotest, crashlog, l1test, and the whole <code>run *test</code> user-program set), and asserts 28 checks on the combined output - boot banner, self-tests, the L0 command count, each test&#39;s PASS line. Zero failures is the bar.</p><h2 id="watchdog-logging-e2e" tabindex="-1">Watchdog / logging E2E <a class="header-anchor" href="#watchdog-logging-e2e" aria-label="Permalink to &quot;Watchdog / logging E2E&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/wp12_watchdog_logging_e2e.py build/opencube.iso</span></span></code></pre></div><p>14 scenarios: klog write/flush/rotation/filter chains, watchdog status/slots/policy kill, health groups + JSON export + CPU alarm, and the two <em>real hardware reset</em> scenarios - S12 boots a q35 machine with <code>-no-reboot</code>, discovers the Intel TCO, arms it, starves it, and asserts the second boot; S13 does the same through ACPI WDAT.</p><h2 id="network-e2e" tabindex="-1">Network E2E <a class="header-anchor" href="#network-e2e" aria-label="Permalink to &quot;Network E2E&quot;">​</a></h2><ul><li><strong>SSH E2E</strong>: starts the in-guest <code>sshd</code>, then logs in from the host through paramiko - full key exchange, session, command round-trip. Requires the /etc volume seeded with host keys (<code>host_keygen_etc</code>).</li><li><strong>HTTPS E2E</strong>: <code>wget https://&lt;host&gt;</code> against a reference TLS server - handshake, certificate verification, body saved, close_notify.</li></ul><p>Both suites are release gates; see <a href="./e2e-suites.html">e2e-suites.md</a> for their full mechanics.</p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make shot-bios     # boot screenshot to build/shot-bios.ppm</span></span>
<span class="line"><span>make shot-uefi</span></span></code></pre></div><h2 id="qemu-devices-that-map-to-drivers" tabindex="-1">QEMU devices that map to drivers <a class="header-anchor" href="#qemu-devices-that-map-to-drivers" aria-label="Permalink to &quot;QEMU devices that map to drivers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>QEMU flag</th><th>Kernel driver</th></tr></thead><tbody><tr><td><code>-device e1000</code> (default net)</td><td>e1000 NIC</td></tr><tr><td><code>-device virtio-blk-pci</code></td><td>virtio-blk</td></tr><tr><td><code>-device nvme</code></td><td>NVMe</td></tr><tr><td><code>-device usb-storage</code> through xHCI</td><td>USB MSC</td></tr><tr><td><code>-device AC97</code> / <code>-device intel-hda</code></td><td>sound</td></tr><tr><td>q35 machine</td><td>Intel TCO watchdog</td></tr><tr><td><code>-bios OVMF.fd</code></td><td>UEFI boot path</td></tr></tbody></table><h2 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h2><ul><li><code>-display none -serial mon:stdio</code> for every automated run.</li><li>Boot to the <code>oc&gt;</code> prompt takes ~2 s of wall time in the regression environment; the full 28-check battery runs in well under a minute.</li></ul>`,21)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
